-- Labels per org (and optionally branch) for neutral keys: programme, section, learner, guardian, staff, term, academic_year, subject, wing, period, admission. Defaults by organizations.kind come from app.default_term().
create table core.terminology (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references core.organizations(id) on delete cascade,
  branch_id uuid,
  key text not null check (key ~ '^[a-z][a-z0-9_.]*$'),
  locale text not null default 'en' check (locale in ('en','hi','te')),
  singular text not null,
  plural text,
  created_at timestamptz not null default now(),
  created_by uuid default app.uid(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  unique (org_id, id),
  foreign key (org_id, branch_id) references core.branches(org_id, id),
  unique nulls not distinct (org_id, branch_id, key, locale)
);
create index terminology_branch on core.terminology(org_id, branch_id);
create trigger trg_touch before update on core.terminology for each row execute function app.touch_updated_at();
grant select, insert, update, delete on core.terminology to authenticated, crm_server, os_server, erp_server;
grant select on core.terminology to platform_admin_server;
select app.apply_core_rls('terminology', 'members', '*', 'setup', null, null);

-- Index of every stored object (plan 4.7). storage_path always starts with "{org_id}/".
create table core.files (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references core.organizations(id) on delete cascade,
  branch_id uuid,
  bucket text not null default 'core-files' check (bucket in ('core-files','crm-files','os-files','erp-files')),
  storage_path text not null,
  file_name text,
  mime text,
  size_bytes bigint check (size_bytes is null or size_bytes >= 0),
  sha256 text,
  owner_type text,
  owner_id uuid,
  product_key text references core.products(key),
  uploaded_by uuid default app.uid(),
  retention_until date,
  created_at timestamptz not null default now(),
  created_by uuid default app.uid(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  unique (org_id, id),
  foreign key (org_id, branch_id) references core.branches(org_id, id),
  unique (bucket, storage_path),
  check (split_part(storage_path, '/', 1) = org_id::text)
);
create index files_branch on core.files(org_id, branch_id);
create index files_owner on core.files(org_id, owner_type, owner_id);
create trigger trg_touch before update on core.files for each row execute function app.touch_updated_at();
grant select, insert, update, delete on core.files to authenticated, crm_server, os_server, erp_server;
grant select on core.files to platform_admin_server;
select app.apply_core_rls('files', 'staff', '*', 'files', null, null);

